------------ import ------------
local UIModule = CS.Engine.UI.UIModule
local KTool = CS.Engine.Lib.KTool
------------ import ------------
local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
local ActionComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
local CommonPlayerHeadNode = "Game.Behaviours.CommonPlayerHeadNode"
local CountDownTime = 2592000 --30 * 86400 30天的秒数
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local FontStyleButton = CS.Game.Native.Common.FontStyleButton

--- from: Assets/BundleResources/Prefabs/Action/ActionTeamInvitePopup.prefab > name: Cell
---@class UIActionTeamInvitePopupNode
---@field Env                           	UIActionTeamInvitePopupNode             
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field STxt_Power                    	Game.Native.Common.UISwitchTextMeshPro  
---@field SImg_Power                    	Game.Native.Common.UISwitchImage        
---@field FriendEmptyCardGroup          	UnityEngine.RectTransform               
---@field TxtCombatPower                	UnityEngine.RectTransform               
---@field FontStyleButton               	UnityEngine.RectTransform               
---@field CommonSmallHeadNode3          	UnityEngine.RectTransform               
---@field CommonSmallHeadNode2          	UnityEngine.RectTransform               
---@field CommonSmallHeadNode1          	UnityEngine.RectTransform               
---@field HeadGroup                     	UnityEngine.RectTransform               
---@field CommonPlayerHeadNode          	UnityEngine.RectTransform               
---@field TxtTime                       	UnityEngine.RectTransform               
---@field TxtLv                         	UnityEngine.RectTransform               
---@field TxtName                       	UnityEngine.RectTransform               
local UIActionTeamInvitePopupNode = Class("UIActionTeamInvitePopupNode")
function UIActionTeamInvitePopupNode:__init()
    self._commonPlayerHeadNodeScr = nil

    self._data = nil
    self._cb = nil
    self._type = nil
end

function UIActionTeamInvitePopupNode:__delete()
    self._commonPlayerHeadNodeScr = nil

    self._data = nil
    self._cb = nil
    self._type = nil
end

function UIActionTeamInvitePopupNode:Awake()
    if not self._commonPlayerHeadNodeScr then
        self._commonPlayerHeadNodeScr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, CommonPlayerHeadNode)
    end
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnInvite))
end

function UIActionTeamInvitePopupNode:Start()
end

function UIActionTeamInvitePopupNode:Refresh(data, type, cb, comp)
    if not data then
        return
    end
    self._data = data
    self._cb = cb
    self._type = type
    self._comp = comp

    self:FillSelf()
end

function UIActionTeamInvitePopupNode:FillSelf()
    if self._commonPlayerHeadNodeScr then        
        local avatar = self._data.playerInfo.avatar
        local avatarFrame = self._data.playerInfo.avatarFrame
        self._commonPlayerHeadNodeScr:FreshAvatarFrame(avatar, avatarFrame)
    end

    CfUtils.FillText(self.TxtLv, "Lv"..self._data.playerInfo.level)
    CfUtils.FillText(self.TxtName, self._data.playerInfo.name)
    -- 战力
    if self._data.combatVal == 0 then
        self.SImg_Power.Status = 2
        self.STxt_Power.Status = 2
        CfUtils.FillText(self.TxtCombatPower, "------")
    else
        self.SImg_Power.Status = 1
        self.STxt_Power.Status = 1
        CfUtils.FillText(self.TxtCombatPower, self._data.combatVal)
    end

    self:FillCards()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnInvite))

    -- 如果是离线的好友，打开离线的黑色遮罩
    if checkNumber(self._type) == 2 
    and isNotNull(self._data.isOnline) 
    and checkNumber(self._data.isOnline) == 0 then
        KTool.SetActive(self.FontStyleButton, false)
        KTool.SetActive(self.controller.transform:Find("OfflineGroup"), true)
    else
        KTool.SetActive(self.FontStyleButton, true)
        KTool.SetActive(self.controller.transform:Find("OfflineGroup"), false)
    end

    -- 邀请按钮的默认状态
    KTool.SetActive(self.TetNum, false)
    local fsb = self.FontStyleButton:GetComponent(typeof(FontStyleButton))
    if isNotNull(fsb) then
        fsb:ResetFontStyle("B12")
    end

    -- 读取单个好友ai可邀请的最大次数
    local max = self._comp:GetFriendInviteLimit()
    if isNull(max) then
        return
    end
    local inviteTimesMax = checkNumber(max)
    if inviteTimesMax <= 0 then
        return
    end

    -- 设置单个好友ai可邀请的最大次数
    local type = checkNumber(self._type)
    if type == 3 or type == 6 then
        -- 如果好友可邀请次数用光了，按钮置灰
        local remainInviteTimes = checkNumber(self._data.remainInviteTimes)
        if remainInviteTimes <= 0 then
            if isNotNull(fsb) then
                fsb:ResetFontStyle("B19")    
            end
        end
        -- 显示可邀请次数
        KTool.SetActive(self.TetNum, true)
        CfUtils.FillText(self.TetNum, string.format("(%d/%d)", remainInviteTimes, inviteTimesMax))
    end
end

function UIActionTeamInvitePopupNode:FillCards()
    local t = checkTable(self._data.cardTeam)

    local count = 0
    for k, v in pairs(t) do
        local headNode = self.HeadGroup:GetChild(count).gameObject
        self:FillCard(headNode, v)
        count = count + 1
    end

    for i = 1, self.HeadGroup.childCount, 1 do
        local headNode = self.HeadGroup:GetChild(i-1)
        local emptyNode = self.FriendEmptyCardGroup:GetChild(i-1)
        KTool.SetActive(headNode, i <= count)
        KTool.SetActive(emptyNode, i > count)
    end
end

function UIActionTeamInvitePopupNode:FillCard(go, data)
    if not go or not data then
        return
    end
    CfUtils.SetActive(go, true)
    -- print(go, table.dump(data))
    CfUtils.RefeshCommonSmallHeroGo(go, data)
end

function UIActionTeamInvitePopupNode:RefreshRemainTime(remainTime)
    self._data.remainTime = checkNumber(remainTime)
    self:FillBtnInfo()

    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self._data.remainTime = checkNumber(self._data.remainTime) - 1
        self:FillBtnInfo()
    end, CountDownTime, false, true)
end

function UIActionTeamInvitePopupNode:FillBtnInfo()
    if checkNumber(self._data.remainTime) > 0 then
        CfUtils.FillText(self.FontStyleButton.transform:Find("Text"), (checkNumber(self._data.remainTime)))
    else
        CfUtils.FillText(self.FontStyleButton.transform:Find("Text"), localize("邀请"))
    end
end

function UIActionTeamInvitePopupNode:OnInvite()
    if checkNumber(self._data.remainTime) > 0 then
        GameUtils.Toast(localize("已邀请"))
        return
    end

    if self._cb then
        self._cb()
    end
end

function UIActionTeamInvitePopupNode:OnDestroy()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActionTeamInvitePopupNode